        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == "run_agent":
            return [a.arg for a in node.args.args]
    return None; old = params(os.path.join(os.environ["ORIGINAL_DIR"], "run_buggy.py")); new = params(os.path.join(os.environ["TARGET_DIR"], "run_buggy.py")); assert new == old, f"run_agent parameters changed: {old} -> {new}"; print("run_agent interface: OK", new)' && echo "" && echo "=== 3. Diff summary ===" && diff -rq --exclude="*.pyc" --exclude="__pycache__" "$ORIGINAL_DIR" "$TARGET_DIR" 2>/dev/null | grep "^Files" || echo "(no file differences)" && echo "" && echo "=== All checks passed ==="

